import sys, os
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, os.path.join(HERE, '..', '..')); sys.path.insert(0, os.path.join(HERE, '..', '..', '..', '..'))
import aeneid_lib as A
# aeneid-035 draft. Drafted from the Latin and grammar only. t is cut from the edition, never typed.
TITLE = 'Pugilum certamen. Entellus et Dares'
TITLE_EN = "The Boxing Match: Entellus and Dares — Aeneid V.387–484"
PART = "The Boxing Match: Entellus and Dares (V.387–484)"
ABOUT = "No Trojan will face Dares, and the old Sicilian Entellus, who alone has been named as his match, has sat still. Acestes, who sits beside him, taunts him for letting the prize be carried off without a fight, and Entellus answers that it is not the love of glory that has left him but the strength of youth; for the bull and its trimmings he would not have come. He throws down a pair of gloves that belonged to Eryx, his master and Venus's son, stiff with sewn-in lead and iron, and Dares, like everyone else, is struck dumb. Entellus recalls how Eryx wore them against Hercules, then offers to fight on equal terms with the Trojan gloves, and the two men take up their stands, Dares quick on his feet and Entellus heavy, old, and unmoved. Dares presses him like a besieger, and in the end Entellus lunges, misses, and crashes to the ground like a torn-up pine. Stung by shame, he rises in a rage and drives Dares over the whole ground in a hail of blows until Aeneas steps in and stops the fight. Dares is helped away spitting blood and teeth. Entellus takes the bull and, to show the Trojans what his youth could do, kills it with a single blow between the horns, and offers its life to Eryx in place of Dares's, and lays down his gloves and his boxing for good."
U = [
(388, 'herbae:',
 "Here heavy with words Acestes chastises Entellus,\nnearest, as he had sat down on the greening couch of grass:",
 "Here Acestes, who had just sat down beside him on a bank of green turf, rebukes Entellus in weighty words:",
 "A new paragraph. 'Gravis' is predicative with Acestes, 'weightily', and 'dictis' is an ablative of means. 'Castigat' is the historic present. In 'proximus ut… consederat', 'ut' with a pluperfect indicative means 'as soon as', 'just as'; 'proximus' is 'next (to him)'. 'Viridante toro… herbae': 'viridante' is a present participle ('viridare', 'to grow green'), agreeing with 'toro', and 'herbae' is a genitive of definition, 'a couch made of grass', an ablative of place, 'on the greening grass-couch'."),
(391, 'sines?',
 "“Entellus, of heroes once the bravest, in vain,\nso great prizes, so patient, with no contest to be carried off\nwill you allow?",
 "“Entellus, once the bravest of heroes, and bravest in vain, will you stay so patient and let such prizes be carried off without a contest?",
 "'Entelle' is a vocative. 'Heroum' is an old genitive plural in -um (you'll see this constantly), partitive after the superlative 'fortissime', 'bravest of heroes'; 'quondam… frustra' is bitter, 'once the bravest, and for nothing'. 'Tantane' is 'tanta' with the question enclitic '-ne', agreeing with 'dona'. 'Tam patiens' is predicative with the understood subject 'tu', 'so patient'. 'Sines' is the future of 'sino', 'will you allow', and takes the infinitive 'tolli' ('tollo', passive), so 'dona' is the subject accusative of the infinitive, 'prizes to be taken'. 'Nullo certamine' is an ablative of manner, 'without any contest'."),
(392, 'Eryx?',
 "Where now to us that god, our master,\nin vain named, Eryx?",
 "Where now is that god, our master Eryx, whom we have named to no purpose?",
 "'Est' is left out after 'ubi', as it is with each 'ubi' of this speech. 'Nobis' is a dative of reference, 'for us', Acestes speaking for the Sicilians, and 'deus ille magister… Eryx' is a string of nouns in apposition: 'that god, (our) master, Eryx'. Eryx was a Sicilian king, a son of Venus (so a half-brother of Aeneas), killed by Hercules in a bout at the foot of the mountain that bears his name; here he is called a god, as a hero honoured after death. 'Memoratus' is the perfect participle passive of 'memoro', 'named', 'spoken of', and 'nequiquam' is 'in vain'."),
(393, 'tectis?”',
 "Where the fame through all\nTrinacria, and those spoils hanging on your roofs?”",
 "Where is your fame through the whole of Sicily, and those spoils that hang in your house?”",
 "'Ubi' again, with 'est' left out: the repetition 'Ubi… Ubi' is anaphora. 'Omnem Trinacriam' is Sicily, the island of the three capes. 'Spolia illa… pendentia' is 'those spoils hanging', the neuter plural present participle of 'pendeo', 'those well-known trophies'. 'Tuis tectis' is 'on your roofs', a plural for a single house, and is dative or ablative with 'pendentia'. The trophies are the gear of men he beat. The closing mark ends Acestes's speech."),
(394, 'haec:',
 "He, at these words:",
 "To this he replies:",
 "'Ille sub haec' has the verb of speaking left out (you'll see this constantly); 'sub haec' means 'upon these (words)', 'hard on them', a use of 'sub' with the accusative of time. 'Ille' is Entellus. The colon leads to his speech."),
(395, 'metu;',
 "“Not love of praise, nor glory has given way,\ndriven out by fear;",
 "“It is not that love of praise has gone, or that glory has given way, driven out by fear;",
 "'Non… nec' is 'not… nor'. 'Laudis amor' is 'love of praise', an objective genitive. 'Cessit' is the perfect of 'cedo', 'has given way', 'has left', and its subject is the pair 'amor… gloria' with the verb agreeing in the singular with the nearer. 'Pulsa' is the perfect participle passive of 'pello', agreeing with 'gloria', 'driven out', and 'metu' is an ablative of means, 'by fear'."),
(396, 'vires.',
 "but indeed, cold, with old age slowing it,\nthe blood is dull, and the worn-out strengths grow cold in the body.",
 "but the plain fact is that my blood runs cold and dull as old age slows it, and my spent strength is chilling in my body.",
 "'Sed enim' is an idiom, 'but the truth is', 'but in fact', not 'but for'. 'Tardante senecta' is an ablative absolute with a present participle, 'old age slowing (it)', and 'gelidus… sanguis hebet' is 'the cold blood is dull' ('hebeo'); the adjective 'gelidus' is set apart from its noun, at the start of the clause. 'Frigent' is from 'frigeo', 'grow cold', and the '-que' joins it to 'hebet'. 'Effetae' is a feminine nominative plural agreeing with 'vires', 'worn out', 'spent'; 'vires' is the plural of 'vis', 'strength', not a form of 'vir'."),
(398, 'iuventas,',
 "If to me, which once there was, and on which this shameless fellow\nexults, trusting, if now there were that youth,",
 "If I now had the youth that once was mine, and that this shameless fellow trusts in as he struts,",
 "The 'si' clause is long and its verb comes late: 'si… foret illa iuventas', 'if that youth were (mine)'. 'Foret' is an old form of 'esset', imperfect subjunctive of 'sum', in a condition contrary to fact. 'Mihi' is a dative of possession with 'foret'. 'Quae quondam fuerat' is a relative clause ('quae' is feminine, with 'iuventas' as its antecedent, which is placed after it): 'which once had been'. 'Quaque… fidens' has 'qua' as an ablative with 'fidens' ('fido', 'trust in', takes the ablative), 'in which he trusts', and 'improbus iste' is 'that shameless fellow', with a note of contempt, 'iste' meaning Dares. 'Exsultat' is 'leaps about', 'struts'. 'Iuventas' is Virgil's form of 'iuventa'."),
(400, 'moror.',
 "not indeed by a prize led on, and a fine bullock,\nwould I have come, nor do I care for the gifts.”",
 "I would never have come, drawn by a prize and a handsome bullock; and the gifts do not concern me.”",
 "This is the main clause of the condition: 'haud equidem… venissem', 'I would not have come', a pluperfect subjunctive where the 'si' clause was imperfect (a mixed condition, 'if I were as I was, I would then not have come'); 'equidem' is 'for my part', used with the first person. 'Inductus' is the perfect participle passive of 'induco', 'led on'; 'pretio… pulchroque iuvenco' is ablative of means. 'Nec dona moror' has 'moror' in the sense 'I care for', 'I mind', with an accusative, 'I do not care about the gifts'. Misprint: Greenough prints the closing mark of the speech after the full stop and attached to the next word (moror. ”Sic), so the speech seems to open again; the sense is that the speech ends at 'moror.', and 'Sic deinde locutus' is narrative. t keeps the print as it stands, and the closing mark in l and i sits after 'moror.'"),
(403, 'tergo.',
 "Thus then having spoken,\ninto the middle twin gloves of huge weight\nhe threw down, which fierce Eryx, for battles accustomed\nto bear his hand, and to stretch his arms with hard hide.",
 "So saying, he flung down in the midst a pair of gloves of enormous weight, which fierce Eryx used to wear in battle, stretching his arms in the hard hide.",
 "'Locutus' is the perfect participle of the deponent 'loquor', 'having spoken', with active sense. 'Caestus' is an accusative plural (fourth declension), the boxing-gloves of ox-hide, loaded with metal; 'geminos' is 'a pair'; 'immani pondere' is an ablative of quality, 'of huge weight'; 'proiecit' is 'threw down'. 'Quibus' (these gloves) is an ablative of means with the infinitives, and 'suetus' (perfect participle of 'suesco', 'accustomed', with 'erat' left out) takes them: 'ferre manum' is 'to carry the hand', 'to fight', and 'intendere brachia duro tergo' is 'to stretch the arms in the hard hide', 'tergo' being an ablative of means, a singular for a plural ('terga' in 405). 'Acer Eryx': 'acer' is 'keen', 'fierce'."),
(404, 'animi:',
 "Were struck dumb the spirits:",
 "Every heart stood stunned:",
 "'Obstipuere' is 'obstipuerunt', the ending '-ere' for '-erunt' (you'll see this constantly), from 'obstipesco', 'be astounded'. 'Animi' is the subject, 'the minds', that is, 'they all'. The colon leads to the reason."),
(405, 'rigebant.',
 "of so great oxen the huge seven\nhides, with lead sewn in and iron, were stiff.",
 "seven vast hides of such huge oxen stood stiff, with lead sewn into them, and iron.",
 "'Septem' goes with 'terga', 'seven hides', and 'ingentia' with it, set early, with the noun on the next line; 'tantorum… boum' is 'of such great oxen', 'boum' being the irregular genitive plural of 'bos'. 'Plumbo insuto ferroque' is an ablative of means with 'rigebant', 'were stiff with', and 'insuto' is the perfect participle passive of 'insuo', 'sewn in'; 'ferro' is joined to 'plumbo' by '-que'. 'Rigebant' is imperfect of 'rigeo', 'be stiff'."),
(406, 'recusat;',
 "Before all is stunned Dares himself, and far off refuses;",
 "Dares himself is the most amazed of all, and keeps well back and refuses;",
 "A new paragraph. 'Ante omnes' is 'before all', 'above all (others)', and 'ipse' stresses 'Dares himself'. 'Stupet' is 'is struck dumb'. 'Longe' is an adverb, 'far off', 'right away', with 'recusat', 'refuses (the fight)'. Greenough prints 'omnes', 'all'; the Latin Library has the same word in another form ('omnis')."),
(408, 'versat.',
 "and great-souled Anchises' son both the weight and the very\nhere and there, of the straps, immense coils turns over.",
 "and great-hearted Aeneas, Anchises' son, turns over and over the weight of them and the huge coils of their straps.",
 "'Anchisiades' is a patronymic, 'son of Anchises', that is, Aeneas; 'magnanimus' is 'great-souled'. 'Et pondus et ipsa… volumina' is 'both the weight and the very coils': 'ipsa' and 'immensa' belong with 'volumina', and 'huc illuc vinclorum' stands in between, so the noun comes last. 'Vinclorum' is 'vinculorum' shortened (a syncopated form), 'of the straps'. 'Versat' is the frequentative of 'verto', 'turns over and over', 'handles'. 'Huc illuc' is 'this way and that'."),
(409, 'voces:',
 "Then the elder such words was bringing from his breast:",
 "Then the old man brought up from his chest words like these:",
 "'Senior' is the comparative of 'senex', 'the older (man)', used as a noun; Entellus. 'Referebat' is imperfect, 'was bringing back', here 'was uttering'; 'pectore' is an ablative of the place from which, 'from his breast'. 'Talis… voces' is 'such words' (accusative plural, in Greenough's '-is' spelling), and the colon leads to the speech."),
(411, 'pugnam?',
 "“What, if anyone the gloves of the man himself and Hercules' arms\nhad seen, and the grim fight on this very shore?",
 "“What if anyone had seen the very gloves, and Hercules' arms with them, and the grim fight on this same shore?",
 "A new paragraph. 'Quid, si…?' is 'what (would you say) if…?', with the main clause left out; 'quis' after 'si' means 'anyone', and 'vidisset' is a pluperfect subjunctive, 'had seen'. 'Caestus ipsius' is 'the gloves of the man himself', most naturally Eryx (the next lines say whose they were), though some take 'ipsius' as Hercules; 'et Herculis arma' is 'and Hercules's arms', the gear he wore against Eryx. 'Tristem… pugnam' is the second object of 'vidisset', 'hoc ipso in litore' 'on this very shore', the preposition coming between the adjectives and the noun."),
(412, 'gerebat;—',
 "These arms your brother Eryx once was wearing;—",
 "Your brother Eryx once wore these arms;—",
 "'Haec… arma' is the object, set early in the line. 'Gerebat' is imperfect, 'used to wear'. 'Germanus… tuus' is 'your brother': the addressee is not named, and the usual view is Aeneas, since Eryx was a son of Venus and so his half-brother (two lines on, Aeneas is spoken of in the third person). The dash opens an aside."),
(413, 'cerebro;—',
 "you see them still stained with blood and with scattered brains;—",
 "you can see them still, stained with blood and splashed brain;—",
 "The aside: 'cernis' is 'you see', and 'infecta' is the neuter plural perfect participle passive of 'inficio', 'stained', agreeing with 'arma' (understood as the object of 'cernis'). 'Sanguine… sparsoque… cerebro' is an ablative of means, 'with blood and scattered brain', 'sparso' being the perfect participle passive of 'spargo'. 'Adhuc' is 'still'."),
(414, 'stetit;',
 "with these against great Alcides he stood;",
 "with these he stood up to mighty Hercules;",
 "'His' is an ablative of means (with these arms); 'Alciden' is the Greek accusative of 'Alcides', 'descendant of Alcaeus', Hercules (Alcaeus was his grandfather); 'contra' follows it, a preposition set after its noun. 'Stetit' is 'took his stand against'."),
(416, 'senectus.',
 "with these I was accustomed,\nwhile better blood gave strength, rival not yet\non both temples was whitening, scattered, old age.",
 "I was used to them while better blood gave me strength, and old age, the rival of youth, had not yet begun to whiten and sprinkle my temples.",
 "'His' is a dative with 'suetus', 'accustomed to these', 'eram' left out. 'Dum… dabat' is 'while… was giving', 'dum' with an imperfect indicative; 'melior… sanguis' is 'better blood', and 'vires' is the object. 'Aemula… senectus' is 'rival old age', rival, that is, to youth; 'necdum' is 'and not yet', 'canebat' is imperfect of 'caneo', 'be white', and 'sparsa' is the perfect participle passive of 'spargo', agreeing with 'senectus', 'scattered' like a sprinkling of grey over 'temporibus geminis', 'both temples', a dative or ablative of place."),
(419, 'pugnas.',
 "But if our arms, these, Dares the Trojan refuses,\nand this is settled for pious Aeneas, approves the sponsor Acestes,\nlet us make the fights equal.",
 "But if Dares the Trojan will have none of these arms of ours, and pious Aeneas is set on it, and Acestes, who urged it, agrees, let us make the fight an even one.",
 "'Nostra… haec… arma' is 'these arms of ours'; 'Troius' is 'Trojan', with 'Dares'; 'recusat' is 'refuses'. 'Id… sedet pio Aeneae' is the idiom 'it is settled for him': 'sedet' is used impersonally of a fixed resolve, and 'pio Aeneae' is a dative of the person. 'Auctor' is an appositive, 'as sponsor', Acestes being the one who urged the match. 'Aequemus' is a jussive (hortatory) subjunctive, 'let us make equal', and 'pugnas' is a plural for 'the fight'."),
(419, 'remitto;',
 "Eryx's hides for you I give up;",
 "I waive the hides of Eryx for your sake;",
 "'Erycis' is the genitive of 'Eryx'. 'Terga' is 'the hides', the leather gloves again (see 405). 'Remitto' is 'I let go', 'I give up', and 'tibi' is a dative of interest, 'for you'."),
(420, 'metus;',
 "loose your fears;",
 "put your fears away;",
 "'Solve' is the imperative of 'solvo', 'loosen', 'set free', and 'metus' is the accusative plural (fourth declension) of 'metus', 'fear', 'put off your fears'."),
(420, 'caestus.”',
 "and you strip off the Trojan gloves.”",
 "and you, take off those Trojan gloves.”",
 "'Exue' is the imperative of 'exuo', 'strip off'. 'Et tu' puts the two commands alongside, 'and you, for your part'. 'Troianos caestus' means the Trojan gloves, which Dares has, in place of Eryx's. The closing mark ends Entellus's second speech."),
(423, 'harena.',
 "This having said, double from the shoulders he threw back the cloak\nand the great joints of his limbs, great bones and muscled arms\nhe strips, and huge in the middle sand he takes his stand.",
 "With these words he cast his folded cloak back from his shoulders, bared the great joints of his limbs, his great bones and his muscled arms, and took his stand, huge, in the middle of the sand.",
 "'Fatus' is the perfect participle of the deponent 'for', 'fari', 'having said'. 'Duplicem… amictum' is 'the double cloak', one folded doubled over; 'reiecit' is 'threw back'. 'Exuit' governs both objects: the cloak was 'thrown back' and the body parts 'stripped bare'; 'magnos membrorum artus, magna ossa lacertosque' are 'the great joints of the limbs, the great bones, and the muscular arms' (the 'que' on 'lacertosque'). 'Ingens' is predicative with 'consistit'; 'media harena' is an ablative of place, 'in the middle of the arena'."),
(425, 'armis.',
 "Then sown of Anchises the father brought out gloves equal,\nand with matching arms the palms of both he bound.",
 "Then Father Aeneas brought out a matched pair of gloves and bound the hands of both men with arms alike.",
 "A new paragraph. 'Satus Anchisa… pater' is Aeneas: 'satus', perfect participle of 'sero', 'sown', is followed by an ablative of origin, 'sprung from Anchises'. 'Aequos' is 'matching' (a pair equal in weight). 'Paribus… armis' is an ablative of means, 'with equal arms'; 'palmas amborum' is 'the palms of both'. 'Innexuit' is the perfect of 'innecto', 'bind'."),
(427, 'auras.',
 "Each stood at once on his toes, drawn up,\nand his arms to the upper air, unafraid, raised.",
 "At once each rose upright on tiptoe and, unafraid, raised his arms to the air above.",
 "'Uterque', 'each (of the two)', is singular and takes singular verbs, 'constitit… extulit'. 'In digitos' is 'on the toes' (the accusative after 'in' shows the position they have risen to), and 'arrectus' is the perfect participle passive of 'arrigo', 'drawn up', 'erect'. 'Brachia' is the object of 'extulit' (Greenough's spelling; the usual 'bracchia'). 'Superas… auras' is 'the upper air', and 'interritus' is 'unafraid'."),
(429, 'lacessunt.',
 "They drew back far their lofty heads away from the blow,\nand mingle hands with hands, and provoke the fight.",
 "Far back they drew their tall heads out of the blow's way, then mingled hands with hands and stirred up the fight.",
 "'Abduxere' is 'abduxerunt', the ending '-ere' for '-erunt', 'drew away'; 'retro longe' is 'far back'. 'Capita ardua' is 'their lofty heads', 'ab ictu' 'away from the blow'. 'Immiscent manus manibus' is 'they mix hands with hands': 'immisceo' takes a dative, 'manibus'. 'Lacessunt' is 'provoke', 'start', with 'pugnam' the object."),
(430, 'iuventa;',
 "He better in motion of feet, and relying on youth;",
 "The one is the better in the play of his feet, and relies on his youth;",
 "'Ille' is Dares, the young man, 'hic' (next line) Entellus. 'Est' is left out. 'Pedum motu' is an ablative of respect, 'in movement of the feet', with 'pedum' a genitive dependent on 'motu'. 'Melior' is a comparative, 'better'. 'Fretus' is a perfect participle with the sense 'relying on', followed by an ablative, 'iuventa'."),
(432, 'artus.',
 "this one in limbs and bulk strong, but slow, to him trembling\nthe knees totter, his huge limbs shakes a labouring panting.",
 "the other is strong in limb and bulk, but his slow knees give way under him as he trembles, and a labouring breath shakes his vast frame.",
 "'Valens' is the present participle of 'valeo', 'strong', and 'membris et mole' an ablative of respect. 'Tarda… genua' is neuter plural, 'slow knees', the subject of 'labant', 'totter'. 'Trementi' is a dative, 'to him trembling' (a dative of the person affected, 'his knees give way for him as he trembles'). 'Vastos… artus' is 'huge limbs', object of 'quatit', 'shakes', and 'aeger anhelitus' is 'a sick, labouring panting'; 'anhelitus' is fourth declension."),
(433, 'iactant,',
 "Many blows the men in vain among themselves hurl,",
 "Many blows the men hurl at one another to no purpose,",
 "'Viri' are 'the men'. 'Inter se' is 'at one another'. 'Volnera' (Greenough's spelling; familiar 'vulnera') is 'wounds', here 'blows'; 'multa' agrees with it, and 'iactant' is 'hurl'. 'Nequiquam' is 'in vain'."),
(436, 'malae.',
 "many on the hollow flank they redouble, and from the chest huge\ngive sounds, and strays round ears and temples\nthick a hand, under the hard blow crack the jaws.",
 "many they redouble on the hollow flank, and the chest gives out heavy thuds; thick and fast a fist strays about ears and temples, and the jaws crack under the hard blows.",
 "'Multa' is a neuter plural object ('volnera' understood from the line before), and 'ingeminant' takes the dative 'cavo lateri', 'on the hollow flank'. 'Pectore' is an ablative of the source, 'from the chest', with 'dant vastos sonitus', 'give out huge sounds' ('sonitus' is an accusative plural of the fourth declension). 'Errat… crebra manus' is 'a thick (rapid) hand wanders': 'manus' is singular, a fist after fist, and 'auris' is Greenough's accusative plural 'ears'; 'circum' follows both 'auris et tempora'. 'Duro… sub volnere' is 'under the hard blow', and 'malae' (nominative plural) are 'the jaws'."),
(438, 'exit.',
 "Stands heavy Entellus and by the same effort unmoved,\nwith body the missiles only and with watchful eyes he avoids.",
 "Entellus stands heavy and unmoving in the same stance, avoiding the blows with a sway of the body alone and with watchful eyes.",
 "A new paragraph. 'Gravis' is predicative, 'heavy', 'weighty'; 'nisu… eodem' is an ablative of respect, 'in the same stance' ('nisus', 'effort', 'posture'). 'Corpore tela modo atque oculis vigilantibus exit' is 'he avoids the missiles with the body alone and with watchful eyes': 'modo' here means 'only'; 'tela', the 'missiles', are the blows, and 'exit' is a present of 'exeo' with an accusative, 'goes out from', 'evades'."),
(442, 'urguet.',
 "He, like one who a lofty city assaults with siege-mounds,\nor mountain forts sits round beneath arms,\nnow these, now those approaches, and the whole place ranges over\nwith skill, and with various onsets in vain presses.",
 "Dares is like a man who storms a lofty city with siege-works, or sits in arms around a hill-fort: now at this approach, now at that, he ranges over the whole ground with skill, and presses on to no effect with attack after varied attack.",
 "'Ille' is Dares, and the whole comparison is a simile with 'velut… qui', 'like one who', followed by the present tense: 'oppugnat', 'sedet'. 'Celsam… urbem' is 'a lofty city', 'molibus' an ablative of means, 'with mounds', siege-works. 'Sedet… circum' is 'sits round', that is, besieges ('circum' set after its noun); 'montana castella' is 'hill-forts', 'sub armis' 'under arms'. 'Nunc hos, nunc illos aditus' is 'now these, now those approaches' (the object of 'pererrat'), and 'omnemque… locum', 'the whole ground', goes with it; 'arte' is an ablative of manner, 'with skill'. 'Inritus' is a predicative adjective, 'in vain', 'to no effect'. 'Urguet' is Greenough's spelling of 'urget', 'presses'. 'Variis adsultibus' is an ablative of means, 'with varied assaults'."),
(444, 'extulit:',
 "Shows his right hand rising up Entellus, and on high\nlifted it:",
 "Rising to his full height, Entellus shows his right hand, and lifts it on high:",
 "'Insurgens' is the present participle of 'insurgo', 'rising up', agreeing with 'Entellus'. 'Ostendit dextram' is 'shows the right hand' as a threat; 'extulit' is 'raised', 'alte', 'on high'. The colon introduces what follows."),
(445, 'cessit.',
 "he the blow coming from the top, swift,\nforesaw, and with nimble body slipped out and yielded.",
 "but Dares, quick, saw the blow coming down from above and slipped out of its way with a nimble twist of the body.",
 "'Ille' now is Dares. 'Ictum venientem' is 'the blow coming', a present participle; 'a vertice' is 'from the top', 'from above'. 'Velox' is predicative, 'swift'; 'praevidit' is 'foresaw'. 'Elapsus' is the perfect participle of the deponent 'elabor', 'having slipped away', and 'celeri… corpore' an ablative of means, 'with a nimble body'; 'cessit' is 'gave way'."),
(449, 'pinus.',
 "Entellus strength into the wind poured out, and moreover\nhimself heavy and heavily to the ground with vast weight\nfell, as sometimes hollow falls either on Erymanthus,\nor on Ida the great, by the roots torn up, a pine.",
 "Entellus spent his strength upon the wind and then, heavy as he was, came heavily down to the ground with all his vast weight, as a hollow pine falls, uprooted, on Erymanthus or on great Ida.",
 "'Vires in ventum effudit' is 'poured out strength into the wind', 'wasted it'. 'Ultro' here means 'of his own accord', 'besides': his own blow brings him down. 'Gravis graviterque' is 'heavy and heavily', an adjective and an adverb of one root side by side. 'Pondere vasto' is an ablative of cause or manner, 'with his huge weight'. In the simile, 'ut quondam' is 'as sometimes': 'quondam' is 'at times', of a recurring event, and 'concidit' is a perfect used for what happens often (a general statement). 'Cava… pinus' is 'a hollow pine'; 'eruta' is the perfect participle passive of 'eruo', 'torn up', and 'radicibus' an ablative of separation, 'by the roots'. 'Erymantho' is an ablative of place with no 'in' (poetry's way); 'Ida in magna' puts the preposition between the adjective and the noun."),
(450, 'pubes;',
 "Rise together with eagerness the Teucrians and the Trinacrian youth;",
 "The Trojans and the young men of Sicily spring up in their eagerness;",
 "'Consurgunt' is 'rise together'. 'Studiis' is an ablative of manner, 'with eagerness', 'with partisan zeal'. 'Teucri' is the Trojans; 'Trinacria pubes' is 'the Sicilian youth', 'pubes' being a feminine noun for 'the young men'."),
(452, 'amicum.',
 "goes a shout to the sky, and first runs up Acestes,\nand his coeval from the ground pitying lifts up his friend.",
 "A shout goes up to heaven, and Acestes is the first to run to him, and lifts his friend, who is his own age, from the ground in pity.",
 "'It clamor caelo': 'it' is 'goes', from 'eo', and 'caelo' is a dative of the direction, as often in verse. 'Primus' is predicative, 'first'. 'Aequaevum… amicum' is 'his friend of the same age', 'aequaevus' agreeing with 'amicum' and set far from it. 'Miserans' is the present participle of the deponent 'miseror', 'pitying'. 'Ab humo' is 'from the ground'."),
(454, 'ira.',
 "But not slowed by the fall nor frightened the hero\nkeener to the fight returns and force rouses with anger.",
 "But the hero, neither checked by his fall nor dismayed, goes back to the fight with a keener edge, and rouses his force with rage.",
 "'Tardatus' is the perfect participle passive of 'tardo', 'slowed', 'checked', and 'casu' an ablative of cause, 'by the fall'. 'Territus' is 'frightened'. 'Heros' is a Greek nominative. 'Acrior' is the comparative of 'acer', predicative, 'keener', 'fiercer'. 'Vim suscitat ira' is 'rouses (his) force with anger', 'ira' being an ablative of means."),
(457, 'sinistra;',
 "Then shame fires his strength and conscious valour,\nand headlong Dares blazing he drives over the whole plain,\nnow with right hand redoubling blows, now he with left;",
 "Then shame and a courage that knows its own worth set his strength alight, and, blazing, he drives Dares headlong over the whole floor, doubling his blows now with the right hand, now with the left;",
 "A subject of two nouns takes a singular verb, 'pudor… et… virtus… incendit'; 'conscia' is 'aware' (of its own past), 'virtus' is 'courage'. 'Praecipitem' is predicative, 'headlong'; 'Daren' is the Greek accusative of 'Dares', 'ardens' is 'blazing', and 'aequore toto' is an ablative of the space over which, 'over the whole plain' (the level floor of the fight). 'Nunc dextra ingeminans ictus, nunc ille sinistra': 'dextra' and 'sinistra' are ablatives, 'with the right hand', 'with the left' ('manu' understood), and 'ille' is Entellus, with 'ingeminans ictus' to be supplied again from the first half."),
(458, 'requies:',
 "no delay, no rest:",
 "no pause, no respite:",
 "'Nec mora, nec requies' has 'est' left out: 'no delay, no rest'. The colon leads to a simile."),
(460, 'Dareta.',
 "as thick with hail the storm-clouds\non roofs rattle, so with thick blows the hero\nthick with each hand batters and turns Dares about.",
 "as the storm clouds rattle on the rooftops with a thick fall of hail, so the hero, crowding in on him, batters Dares and spins him round with thick blows from either hand.",
 "'Quam… sic' is a comparison of 'as… so'. 'Quam multa grandine' is 'with how much hail', 'as thickly with hail', 'multa' agreeing with 'grandine'; 'nimbi' is 'storm-clouds', the subject, and 'culminibus' is 'on the roofs', a dative or ablative of place. 'Densis ictibus' is an ablative of means, 'with thick blows'. 'Creber' is a nominative, 'crowding', 'thick', agreeing with 'heros'; 'utraque manu' is 'with each hand'. 'Pulsat versatque' is 'batters and turns about', 'Dareta' the Greek accusative of 'Dares'."),
(462, 'acerbis;',
 "Then father Aeneas, to advance further the angers\nand to rage in bitter passions Entellus, not having allowed;",
 "Then Father Aeneas would not allow the wrath to go further, or Entellus to rage on in such bitter passion;",
 "A new paragraph. 'Haud passus' is 'not having allowed' ('passus', the perfect participle of the deponent 'patior', with 'est' left out); 'haud passus' is a way of saying 'forbade'. It takes the accusative and infinitive twice: 'iras procedere longius', 'the angers to go further', and 'Entellum saevire', 'Entellus to rage'. 'Animis… acerbis' is an ablative of manner, 'with bitter spirit' (the plural 'animis', 'passions')."),
(464, 'fatur:',
 "but an end he put to the fight, and weary Dares\nhe snatched away, soothing with words, and such things says:",
 "but he put an end to the fight, and rescued the worn-out Dares, soothing him with words, and speaks to him thus:",
 "'Finem imposuit pugnae' is 'put an end to the fight', with 'pugnae' a dative after 'impono'. 'Eripuit' is 'snatched away', 'Dareta' the Greek accusative, and 'mulcens' the present participle of 'mulceo', 'soothing', with 'dictis' an ablative of means. 'Fatur' is the present of the deponent 'for' ('fari'); the colon leads to Aeneas's speech."),
(465, 'cepit?',
 "“Unlucky man, what so great madness has seized your mind?",
 "“Wretched man, what madness so great has taken hold of your mind?",
 "'Infelix' is a vocative, 'unlucky one'. 'Quae tanta… dementia' is 'what so great madness', the subject, and 'animum' the object of 'cepit', 'has seized (your) mind', 'te' being understood."),
(466, 'sentis?',
 "Not other strengths and turned divine powers do you feel?",
 "Can you not feel that his strength is of another kind, and that heaven has turned against you?",
 "'Non… sentis?' is a question that expects yes: 'do you not feel?'. 'Vires alias' is 'other (different) strengths', not those he had at the start. 'Conversa… numina' is 'the divine powers turned about', the perfect participle passive of 'converto' agreeing with 'numina', 'turned against you' by implication. Greenough's 'vires' (the Latin Library prints the other spelling 'uiris') is the same word; there is no change of sense."),
(467, 'deo.',
 "Yield to a god.”",
 "Yield to a god.”",
 "'Cede' is the imperative of 'cedo', 'yield', and 'deo' a dative, 'to a god' (an unnamed god in Entellus's strength). Misprint: as at 400, Greenough prints the closing mark after the full stop and attached to the next word (deo. ”Dixitque), so it seems to open a fresh speech. The speech ends at 'deo.'; t keeps the print as it stands, and the closing mark in l and i sits here."),
(467, 'diremit.',
 "And he spoke, and the fights with his voice broke up.",
 "So he spoke, and with his voice he broke up the fighting.",
 "'Dixitque' is narrative, 'and he spoke'. 'Diremit' is the perfect of 'dirimo', 'part', 'break up'; 'proelia' is a plural for the single fight, and 'voce' is an ablative of means, 'by his voice'."),
(471, 'naves;',
 "But him faithful comrades, his knees weak dragging,\nand tossing his head either way, and thick gore\nfrom his mouth spitting out, and teeth mixed in the blood,\nlead to the ships;",
 "But his loyal comrades lead him to the ships, trailing his sagging knees, his head lolling from side to side, spitting thick gore from his mouth, and teeth mixed with the blood;",
 "'Ast' is an old form of 'at', 'but'. 'Illum' (Dares) is the object of 'ducunt', which comes late, in 471; three present participles in the accusative, 'trahentem', 'iactantem', 'eiectantem', agree with it, the last two of them frequentatives ('iacto', 'eiecto'), 'repeatedly tossing', 'repeatedly spitting'. 'Fidi aequales' is 'faithful comrades', 'aequales' being a noun, 'those of the same age'. 'Utroque' is 'to both sides', 'either way'. 'Ore' is an ablative of separation, 'from the mouth'; 'mixtos in sanguine dentes' is 'teeth mixed in the blood'. Greenough's 'naves' (Latin Library 'nauis') is the same word."),
(472, 'accipiunt;',
 "and helmet and sword summoned\nthey receive;",
 "and, being called forward, they take the helmet and the sword;",
 "'Vocati' is the perfect participle passive of 'voco', 'called', the comrades being summoned to receive the loser's consolation gifts; 'galeam ensemque' are 'helmet and sword', the object of 'accipiunt'."),
(472, 'relinquunt.',
 "the palm to Entellus and the bull they leave.",
 "the palm and the bull they leave to Entellus.",
 "'Palmam' is the palm of victory; 'Entello' is a dative, 'to Entellus', and 'relinquunt' is 'they leave'."),
(473, 'superbus:',
 "Here the victor, rising in spirit and proud of the bull:",
 "Here the winner, soaring in spirit and proud of his bull, speaks:",
 "'Hic' is an adverb, 'here', 'at this point'. 'Victor' is predicative, 'as victor'. 'Superans animis' is 'rising high in spirit' ('supero', 'rise above'; 'animis' an ablative of respect); 'tauroque superbus' is 'proud of the bull', 'tauro' an ablative of cause. The verb of speaking is left out, and the colon leads to the speech."),
(476, 'Dareta.”',
 "“Goddess-born, and you, these things, he says, learn, Trojans,\nand to me what there were in a youthful body strengths,\nand by what you save, called back from death, Dares.”",
 "“Son of a goddess, and you Trojans, take note, he says, both of what strength I had in a young man's body, and of the means by which you save Dares, called back from death.”",
 "A new paragraph. 'Nate dea' is a vocative, 'son (nate) of a goddess' ('dea' an ablative of origin), Aeneas; 'vosque… Teucri' turns to the Trojans. 'Inquit' stands in the middle of the speech: a parenthesis, 'he says', and the speech goes on to 476, without any mark in the print around it (the print has no mark there; the sense runs on). 'Haec' is the object of 'cognoscite' and looks forward to the two clauses introduced by 'et… et', both of them indirect questions: 'quae… vires fuerint', 'what strength there was' ('mihi' a dative of possession, 'fuerint' a perfect subjunctive, 'iuvenali in corpore' 'in a youthful body'), and 'qua servetis… Dareta'. In 'qua', the ablative feminine of the interrogative, a noun like 'ope' or 'vi' is understood, 'by what means'; the exact sense is disputed, and here it is read as 'by what means you save Dares' now. 'Revocatum' is the perfect participle passive agreeing with 'Dareta' (a Greek accusative), 'called back from death'."),
(480, 'cerebro.',
 "He spoke, and opposite stood the face of the bullock facing him,\nwhich stood by, the gift for the fight, and the hard, drawn back,\nhe poised, with his right hand, between the middle horns, the gloves,\ntowering, and, the brain shattered, dashed them into the bones.",
 "He spoke, and took his stand face to face with the bullock that stood before him, the prize of the fight, and, drawing back his right hand, poised the hard gloves between the horns; then, rising to his full height, he dashed them against the bone, and the brain burst out.",
 "'Dixit' is 'he spoke'. 'Adversi contra stetit ora iuvenci' is 'stood facing the face of the bullock that faced him': 'adversi' agrees with 'iuvenci', and 'contra' goes with 'ora', 'over against'. 'Qui… adstabat' is a relative clause, 'which stood by', with 'donum pugnae', 'a gift (for) the fight', the apposition to 'qui' (a dative of purpose or a genitive; either reading is possible). Greenough's 'adstabat' (Latin Library 'astabat') is the same word. 'Reducta… dextra' is an ablative absolute, 'the right hand drawn back'; 'libravit' is 'poised'; 'durosque… caestus' is the object, and 'media inter cornua' is 'between the horns', 'inter' set after its noun. 'Arduus' is predicative, 'standing tall'. 'Inlisit in ossa' is 'dashed (them) into the bones', and 'effracto… cerebro' is an ablative absolute, 'the brain being shattered'."),
(481, 'bos.',
 "is laid low, and lifeless, trembling, falls forward on the ground, the bull.",
 "and the bull is laid low, and falls forward on the ground, lifeless, quivering.",
 "'Sternitur' is the present passive of 'sterno', 'is laid low'. 'Exanimis' (lifeless) and 'tremens' (trembling) are predicative, and 'humi' is the locative, 'on the ground'. 'Bos' is the nominative singular, and the subject comes last. Misprint: Greenough prints 'sternitur' with a small letter after the full stop at the end of 480, where a capital is expected; t keeps the print as it stands."),
(482, 'voces:',
 "He over it such pours out from his breast words:",
 "Over the carcass he pours out from his chest words like these:",
 "'Ille' is Entellus. 'Super' is an adverb here, 'over it' (the dead bull); 'effundit pectore voces' is 'pours out words from the chest', 'pectore' an ablative of the source. The colon leads to the speech."),
(484, 'persolvo;',
 "“This for you, Eryx, a better life in place of the death of Dares\nI pay in full;",
 "“Eryx, in place of Dares's death I pay you this better life in full;",
 "'Tibi' is a dative, 'to you', Eryx, 'Eryx' a vocative of the Greek-type noun. 'Hanc… meliorem animam' is 'this better life' ('anima', 'breath', 'life'; the bull's life is called better, an offering worth more than Dares's), and 'pro morte Daretis' is 'in place of the death of Dares' ('Daretis' is a Greek-style genitive). 'Persolvo' is 'I pay in full', the word for discharging a debt or vow."),
(484, 'repono.”',
 "here as victor the gloves and the art I lay down.”",
 "here, a victor, I lay down my gloves and my art.”",
 "'Hic' is an adverb, 'here', 'on this spot'. 'Victor' is predicative, 'as victor'. 'Caestus artemque' is 'the gloves and the skill', both objects of 'repono', 'I lay aside', 'give up'. The closing mark ends Entellus's last speech."),
]
P = A.part('aeneid-035'); L = A.lines_of(P); paras = {l['n'] for l in L if l['p']}
cuts = A.cut(P, [(u[0], u[1]) for u in U])
sents = []; prev_end_line = None
for (t, ln), (_, _t, l, i, n) in zip(cuts, U):
    u = {'t': t, 'l': l, 'i': i, 'n': n}
    if prev_end_line != ln and ln in paras: u['p'] = True
    u['v'] = True; u['ln'] = ln; sents.append(u)
    prev_end_line = ln + t.count('\n')
    if t.count('\n') != l.count('\n'): print('LINE COUNT', ln, repr(t[:30]))
    if '\n' in i: print('NEWLINE IN i', ln)
A.jdump({'title': TITLE, 'titleEn': TITLE_EN, 'part': PART, 'about': ABOUT, 'sentences': sents}, os.path.join(HERE, 'units.json'))
print(len(sents), 'units')
